def checkPalindrome(text):

    # 终止条件
    # 如果字符串的长度大于等于1
    if text == '' or len(text) == 1:
        return True

    # 递归条件
    if text[0] == text[-1]:
        # 返回不包括第一个和最后一个字符的字符串
        return checkPalindrome(text[1:len(text) - 1])

    return False


